/*
 * kat_sweep.c - Exhaustive length sweep for the equivalence test (gcc only)
 *
 * Prints one line per (algorithm, message length):
 *     <algo> <len> <digest hex>
 * for len = 0..256 (the bound of hash_top's input port) and every algorithm
 * supported by the variant, calling hash_top() - the synthesized top.
 * run.sh compares the output with golden.txt, generated by gen_golden.py from
 * independent references (Python hashlib for SHA-3, pyascon for Ascon-Hash256).
 *
 * Why: the 4 KAT of main.c cover the padding byte only in a few lanes.
 * Sweeping every length places the domain-separation byte (0x06 / 0x01) and
 * the final 0x80 in every byte lane of every rate word, and covers every
 * block-boundary case - required to validate the byte <-> word mapping of B-01.
 *
 * Build: -DVARIANT_HYBRID | -DVARIANT_SHA | -DVARIANT_ASCON  (see run.sh)
 */

#include <stdio.h>
#include <stdint.h>
#include "hash.h"

#define MAX_LEN 256

typedef struct {
    const char *name;
    int mdlen;
    uint8_t mode;       /* hybrid only: 0 = Ascon, 1 = SHA3-256, 2 = SHA3-512 */
} algo_t;

#if defined(VARIANT_HYBRID)
static const algo_t ALGOS[] = { {"sha3-256", 32, 1}, {"sha3-512", 64, 2}, {"ascon", 32, 0} };
#elif defined(VARIANT_SHA)
static const algo_t ALGOS[] = { {"sha3-256", 32, 0}, {"sha3-512", 64, 0} };
#elif defined(VARIANT_ASCON)
static const algo_t ALGOS[] = { {"ascon", 32, 0} };
#else
#error "define VARIANT_HYBRID, VARIANT_SHA or VARIANT_ASCON"
#endif

#define NALGOS ((int)(sizeof(ALGOS) / sizeof(ALGOS[0])))

int main(void) {

    uint8_t msg[MAX_LEN], md[64];
    int a, len, i;

    /* same deterministic message as the throughput mode of main.c */
    for (i = 0; i < MAX_LEN; i++) msg[i] = (uint8_t)(i * 167u + 13u);

    for (a = 0; a < NALGOS; a++) {
        for (len = 0; len <= MAX_LEN; len++) {

#if defined(VARIANT_HYBRID)
            hash_top(msg, len, md, ALGOS[a].mdlen, ALGOS[a].mode);
#else
            hash_top(msg, len, md, ALGOS[a].mdlen);
#endif
            printf("%s %d ", ALGOS[a].name, len);
            for (i = 0; i < ALGOS[a].mdlen; i++) printf("%02X", md[i]);
            printf("\n");
        }
    }

    return 0;
}
